registerProvider(
  issuer,
  clientId,
  clientSecret,
  authorizationEndpoint,
  tokenEndpoint,
  redirectionEndpoint,
  usePKCE,
  hostnames,
  scopes,
  useExternalBrowser
) {
  if (kIssuers.has(issuer)) {
    throw new Error(`Issuer ${issuer} already registered.`);
  }
  for (const hostname of hostnames) {
    if (kHostnames.has(hostname)) {
      throw new Error(`Hostname ${hostname} already registered.`);
    }
  }
  const issuerDetails = {
    name: issuer,
    builtIn: false,
    clientId,
    clientSecret,
    authorizationEndpoint,
    tokenEndpoint,
    redirectionEndpoint,
    usePKCE,
    useExternalBrowser,
    useSchemeRedirect: false,
  };
  Object.freeze(issuerDetails);
  kIssuers.set(issuer, issuerDetails);
  for (const hostname of hostnames) {
    kHostnames.set(hostname, [issuer, scopes]);
  }
},
